set statement_timeout='55s'; select string_agg(e||'|'||n_ok||'|'||n_all||'|'||n_q,E'\n') s from (select c.auction_event_id::text e, count(*) filter (where c.comment_text !~* '(\$\s?[0-9]|[0-9]+(\.[0-9])?\s?k\b|sold|hammer|final (bid|price)|winning|reserve)') n_ok, count(*) n_all, count(*) filter (where c.comment_text !~* '(\$\s?[0-9]|[0-9]+(\.[0-9])?\s?k\b|sold|hammer|final (bid|price)|winning|reserve)' and c.reply_count is not null and c.comment_text ~ '@') n_q from auction_comments c join auction_events a on a.id=c.auction_event_id where c.auction_event_id >= '00000000-0000-0000-0000-000000000000' and c.auction_event_id < '04000000-0000-0000-0000-000000000000' and c.is_seller and coalesce(c.comment_type,'')<>'bid' and c.bid_amount is null and c.posted_at < a.auction_end_date group by 1) z